/// <summary>
/// One count of a line, for the supervisor only.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountAttemptRow
{
    int attemptNo;
    real countedQty;
    str userId;
    str countedDateTime;
}

Method.Source:
[DataMemberAttribute('AttemptNo')]
public int parmAttemptNo(int _value = attemptNo)
{
    attemptNo = _value;
    return attemptNo;
}

[DataMemberAttribute('CountedQty')]
public real parmCountedQty(real _value = countedQty)
{
    countedQty = _value;
    return countedQty;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('CountedDateTime')]
public str parmCountedDateTime(str _value = countedDateTime)
{
    countedDateTime = _value;
    return countedDateTime;
}
